  "status_observations": [
    {
      "wording": "Pending",
      "source": "SYN-Office-1 register",
      "as_of": "2026-10-01"
    }
  ],
  "abstract": "A PIR detector wakes a high-power sensing element for a fixed window.",
  "description": "A battery-powered occupancy sensor keeps its high-power sensing element off. A passive infrared detector wakes the high-power element for a fixed observation window when motion is detected, and the element is switched off again if no occupant is classified within the window.",
  "claims": [
    {
      "number": 1,
      "depends_on": null,
      "text": "A battery-powered occupancy sensor comprising a passive infrared detector and a high-power sensing element, wherein the passive infrared detector wakes the high-power sensing element for a fixed observation window upon detecting motion, and the high-power sensing element is switched off if no occupant is classified within the window."
    }
  ]
}

